// Collision response with impulse calculation
function resolveCollision(projectile, target) {
    const overlap = calculateOverlap(projectile, target);
    const normal = normalize(vec2(overlap.x, overlap.y));

    // Apply impulse to both objects
    projectile.velocity = reflectVector(projectile.velocity, normal);
    target.velocity = vec3.add(target.velocity, 
                               scaleVec3(normal, 5.0 * projectile.mass));
}
